ALTER TABLE categories ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE categories ADD COLUMN enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1));
ALTER TABLE categories ADD COLUMN created_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE categories ADD COLUMN updated_at INTEGER NOT NULL DEFAULT 0;
UPDATE categories SET description='Messages related to ' || name || '. Edit this description to define what belongs in this category.', created_at=CAST(unixepoch('subsec')*1000 AS INTEGER), updated_at=CAST(unixepoch('subsec')*1000 AS INTEGER);
-- Preserve references even for direct SQL callers; old cascading FKs remain unchanged.
CREATE TRIGGER categories_restrict_delete BEFORE DELETE ON categories
WHEN EXISTS(SELECT 1 FROM email_categories WHERE account_id=OLD.account_id AND category_id=OLD.id)
 OR EXISTS(SELECT 1 FROM classification_results WHERE account_id=OLD.account_id AND category_id=OLD.id)
BEGIN SELECT RAISE(ABORT, 'category referenced'); END;
WITH defaults(name,description) AS (VALUES ('Job Applications','Applications submitted for employment, application acknowledgments, recruiter updates, and decisions about job opportunities.'),('Job Interviews','Interview invitations, scheduling, preparation instructions, assessments, and follow-up conversations with hiring teams.'),('School','Coursework, classes, enrollment, academic deadlines, campus announcements, and communication with teachers or classmates.'),('Finance','Banking, credit cards, investments, loans, taxes, account statements, and other financial account matters.'),('Receipts','Purchase confirmations, itemized receipts, paid invoices, order details, shipping updates, and refunds.'),('Newsletters','Recurring editorial updates, subscriptions, digests, announcements, and promotional mailing lists.'),('Personal','Conversations with friends and family, personal plans, invitations, and everyday non-work correspondence.')) INSERT INTO categories(id,account_id,name,description,enabled,created_at,updated_at) SELECT lower(hex(randomblob(16))),a.id,d.name,d.description,1,CAST(unixepoch('subsec')*1000 AS INTEGER),CAST(unixepoch('subsec')*1000 AS INTEGER) FROM accounts a CROSS JOIN defaults d WHERE true ON CONFLICT(account_id,name) DO NOTHING;
CREATE TRIGGER account_default_categories AFTER INSERT ON accounts BEGIN
INSERT INTO categories(id,account_id,name,description,enabled,created_at,updated_at) VALUES(lower(hex(randomblob(16))),NEW.id,'Job Applications','Applications submitted for employment, application acknowledgments, recruiter updates, and decisions about job opportunities.',1,NEW.created_at,NEW.created_at);
